涉及publicKey加密的代码123456789101112131415def rsa_oaep_encrypt_fix(self, pub_key, plaintext): try: pub_key_clean = pub_key.replace(&#x27;
&#x27;, &#x27;&#x27;).replace(&#x27; &#x27;, &#x27;&#x27;) pub_key_pem = f&quot;-----BEGIN PUBLIC KEY-----
&#123;pub_key_clean&#125;
-----END PUBLIC KEY-----&quot; public_key = serialization.load_pem_public_key(pub_key_pem.encode(&#x27;utf-8&#x27;), backend=default_backend()) oaep_padding = rsa_padding.OAEP( mgf=rsa_padding.MGF1(algorithm=hashes.SHA256()), algorithm=hashes.SHA256(), label=b&#x27;&#x27; ) encrypted_block = public_key.encrypt(plaintext.encode(&#x27;utf-8&#x27;), oaep_padding) return base64.b64encode(encrypted_block).decode(&#x27;utf-8&#x27;) except Exception as e: self.log(f&quot;RSA-OAEP加密失败: &#123;str(e)&#125;&quot;) raise  PrivateAPIService(BasePrivateApiService): &quot;&quot;&quot; 动态私有OpenAPI 获取 access_token 当参数中包含 month 时，执行预提工资数据推送，并记录每个部门的推送日志 &quot;&quot;&quot; def rsa_oaep_encrypt_fix(self, pub_key, plaintext): try: pub_key_clean = pub_key.replace(&#x27;
&#x27;, &#x27;&#x27;).replace(&#x27; &#x27;, &#x27;&#x27;) pub_key_pem = f&quot;-----BEGIN PUBLIC KEY-----
&#123;pub_key_clean&#125;
-----END PUBLIC KEY-----&quot; public_key = serialization.load_pem_public_key(pub_key_pem.encode(&#x27;utf-8&#x27;), backend=default_backend()) oaep_padding = rsa_padding.OAEP( mgf=rsa_padding.MGF1(algorithm=hashes.SHA256()), algorithm=hashes.SHA256(), label=b&#x27;&#x27; ) encrypted_block = public_key.encrypt(plaintext.encode(&#x27;utf-8&#x27;), oaep_padding) return base64.b64encode(encrypted_block).decode(&#x27;utf-8&#x27;) except Exception as e: self.log(f&quot;RSA-OAEP加密失败: &#123;str(e)&#125;&quot;) raise def log(self, log_content): log_info = &#123; &quot;log_type&quot;: &quot;pushFinanceData&quot;, &quot;create_time&quot;: datetime.datetime.now().strftime(&#x27;%Y-%m-%d %H:%M:%S&#x27;), &quot;content&quot;: str(log_content) &#125; CustomerUtil.call_open_api(&quot;hcm.model.create&quot;, &#123;&quot;model&quot;:&quot;dynamic_log&quot;, &quot;info&quot;:log_info&#125;) def execute(self, **kwargs): if &#x27;month&#x27; in kwargs: return self._push_salary(kwargs) else: return self._get_access_token(kwargs) def _get_access_token(self, kwargs): try: self.log(&#x27;=== 开始获取access_token ===&#x27;) self.log(f&#x27;输入参数: &#123;kwargs&#125;&#x27;) token_url = &quot;http://11.11.11.11:1111/nccloud/opm/accesstoken&quot; client_id = &quot;ldlldldldl&quot; biz_center = &quot;ncc22222&quot; client_secret_raw = &#x27;78544c%^&amp;UI41b111101&#x27; pubKey = &quot;&quot; encrypted_secret = self.rsa_oaep_encrypt_fix(pub_key=pubKey, plaintext=client_secret_raw) client_secret = encrypted_secret signature = &quot;12345678bbe5c8f5c12&quot; token_data = &#123; &quot;grant_type&quot;:&quot;client_credentials&quot;, &quot;biz_center&quot;:biz_center, &quot;client_id&quot;:client_id, &quot;client_secret&quot;:client_secret, &quot;signature&quot;:signature &#125; headers = &#123;&#x27;Content-type&#x27;:&#x27;application/x-www-form-urlencoded;charset=utf-8&#x27;, &#x27;User-Agent&#x27;:&#x27;Java/1.8.0_202&#x27;&#125; response = requests.post(token_url, headers=headers, data=token_data, timeout=30, verify=False) response.encoding = &#x27;utf-8&#x27; self.log(f&quot;响应状态码: &#123;response.status_code&#125;&quot;) self.log(f&quot;响应内容: &#123;response.text&#125;&quot;) response.raise_for_status() return response.json() except Exception as e: self.log(f&quot;获取access_token异常: &#123;str(e)&#125;&quot;) raise e def _push_salary(self, kwargs): try: self.log(&quot;开始执行预提工资推送&quot;) month = kwargs.get(&quot;month&quot;) program_id = kwargs.get(&quot;program_id&quot;) debug_mode = kwargs.get(&quot;debug_mode&quot;, False) self.log(f&quot;推送月份: &#123;month&#125;, program_id: &#123;program_id&#125;, debug_mode: &#123;debug_mode&#125;&quot;) if not month or not program_id: return &#123;&quot;error&quot;: &quot;缺少必要参数 month 或 program_id&quot;&#125; model_name = f&quot;salary_calculate_data.+&#123;program_id&#125;&quot; filter_dict = &#123;&quot;month&quot;: month, &quot;program_id&quot;: program_id&#125; self.log(f&quot;查询模型: &#123;model_name&#125;, 过滤条件: &#123;filter_dict&#125;&quot;) # ---------- 查询当月所有工资明细---------- page_index = 1 page_size = 1000 all_data = [] while True: result = CustomerUtil.call_open_api(&quot;hcm.model.list&quot;, &#123; &quot;model&quot;:model_name, &quot;filter_dict&quot;:&#123;&quot;month&quot;:month, &quot;program_id&quot;:program_id&#125;, &quot;page_index&quot;:page_index, &quot;page_size&quot;:page_size &#125;) data_list = result.get(&quot;list&quot;, []) all_data.extend(data_list) if len(data_list) &lt; page_size: break page_index += 1 if not all_data: self.log(&quot;当月无工资数据&quot;) return &#123;&quot;result&quot;: &quot;无数据&quot;&#125; # ---------- 打印第一条数据的部分信息 ---------- if all_data: self.log(&quot;第一条数据 depart: &quot; + json.dumps(all_data[0].get(&quot;depart&quot;), ensure_ascii=False)) self.log(&quot;第一条数据 balance: &quot; + json.dumps(all_data[0].get(&quot;balance&quot;), ensure_ascii=False)) # ---------- 按部门汇总实发合计，同时记录部门编号和部门名称 ---------- dept_summary = &#123;&#125; # 格式: &#123;dept_id: &#123;&quot;amount&quot;: float, &quot;number&quot;: str, &quot;name&quot;: str&#125;&#125; for item in all_data: dept_id = item.get(&quot;depart_id&quot;) depart_obj = item.get(&quot;depart&quot;) if not dept_id or not depart_obj: continue dept_number = depart_obj.get(&quot;number&quot;) dept_name = depart_obj.get(&quot;name&quot;) balance_obj = item.get(&quot;balance&quot;) actual = balance_obj.get(&quot;salary_real&quot;) if balance_obj else 0 if not dept_number or not dept_name: self.log(f&quot;部门信息不全，跳过: dept_id=&#123;dept_id&#125;, number=&#123;dept_number&#125;, name=&#123;dept_name&#125;&quot;) continue try: amount = float(actual or 0) except: amount = 0.0 if dept_id not in dept_summary: dept_summary[dept_id] = &#123;&quot;amount&quot;: 0.0, &quot;number&quot;: dept_number, &quot;name&quot;: dept_name&#125; dept_summary[dept_id][&quot;amount&quot;] += amount self.log(f&quot;汇总后部门数量: &#123;len(dept_summary)&#125;&quot;) if debug_mode: self.log(&quot;调试模式开启，返回内部数据&quot;) # 调试模式返回部门详情（包含金额、编号、名称） return &#123; &quot;debug&quot;:True, &quot;month&quot;:month, &quot;program_id&quot;:program_id, &quot;dept_summary&quot;:&#123; dept_id:&#123;&quot;amount&quot;:info[&quot;amount&quot;], &quot;number&quot;:info[&quot;number&quot;], &quot;name&quot;:info[&quot;name&quot;]&#125; for dept_id, info in dept_summary.items() &#125;, &quot;total_actual&quot;:sum(info[&quot;amount&quot;] for info in dept_summary.values()) &#125; # ---------- 固定账号 ---------- creator = &quot;admin03&quot; self.log(f&quot;使用固定账号: &#123;creator&#125;&quot;) pk_trantypeid = &quot;1001A8100000003N5BNM&quot; default_pk_trantypecode = &quot;36D1-Cxx-F1&quot; default_pk_org = &quot;1000000&quot; # 所属组织 default_pk_group = &quot;H&quot; # 所属集团 default_pk_busitype = &quot;&quot; # 业务流程 default_pk_currtype = &quot;CNY&quot; # 币种 default_pk_bankacc_r = &quot;946005010001038901&quot; # 收款银行账号 default_supplier = &quot;1020100&quot; # 供应商编码 children = [] total_actual = 0.0 row_no = 10 for dept_id, info in dept_summary.items(): dept_number = info[&quot;number&quot;] amount = info[&quot;amount&quot;] children.append(&#123; &quot;applysum&quot;:str(amount), &quot;pk_acceptorg&quot;:dept_number, &quot;pk_org&quot;:default_pk_org, &quot;pk_group&quot;:default_pk_group, &quot;pk_busitype&quot;:default_pk_busitype, &quot;pk_currtype&quot;:default_pk_currtype, &quot;pk_supplier&quot;:default_supplier, &quot;pk_bankacc_r&quot;:default_pk_bankacc_r, &quot;rowno&quot;:str(row_no), &quot;applymny&quot;:str(amount) &#125;) total_actual += amount row_no += 10 if not children: return &#123;&quot;error&quot;: &quot;无可推送的部门数据&quot;&#125; # 大写金额 applymny_cap = &quot;零元&quot; parent = &#123; &quot;applymny_cap&quot;:applymny_cap, &quot;applysum&quot;:str(total_actual), &quot;creator&quot;:creator, &quot;pk_trantypeid&quot;:pk_trantypeid, &quot;pk_org&quot;:default_pk_org, &quot;pk_group&quot;:default_pk_group, &quot;pk_busitype&quot;:default_pk_busitype, &quot;pk_currtype&quot;:default_pk_currtype, &quot;pk_supplier&quot;:default_supplier, &quot;pk_bankacc_r&quot;:default_pk_bankacc_r, &quot;pk_trantypecode&quot;:default_pk_trantypecode, &quot;pk_acceptorg&quot;:dept_number &#125; payload = &#123; &quot;parent&quot;:parent, &quot;childrens&quot;:children &#125; self.log(f&quot;推送数据: &#123;json.dumps(payload, ensure_ascii=False)&#125;&quot;) # ---------- 获取 access_token ---------- try: token_resp = self._get_access_token(&#123;&#125;) self.log(f&quot;token接口返回: &#123;json.dumps(token_resp, ensure_ascii=False)&#125;&quot;) except Exception as e: self.log(f&quot;调用token接口异常: &#123;str(e)&#125;&quot;) # 记录失败日志（无部门数据） self._record_pre_accrual_data(month, [], 0.0, False, error_message=f&quot;获取token异常: &#123;str(e)&#125;&quot;) return &#123;&quot;error&quot;: f&quot;获取access_token异常: &#123;str(e)&#125;&quot;&#125; if not token_resp or not token_resp.get(&quot;success&quot;): self.log(&quot;获取access_token失败：返回为空或未成功&quot;) self._record_pre_accrual_data(month, [], 0.0, False, error_message=&quot;获取access_token失败&quot;) return &#123;&quot;error&quot;: &quot;获取access_token失败&quot;&#125; data = token_resp.get(&quot;data&quot;, &#123;&#125;) access_token = data.get(&quot;access_token&quot;) if not access_token: self.log(&quot;无法从返回中提取access_token，请检查接口返回格式&quot;) self._record_pre_accrual_data(month, [], 0.0, False, error_message=&quot;无法提取access_token&quot;) return &#123;&quot;error&quot;: &quot;无法获取access_token&quot;&#125; self.log(f&quot;成功获取access_token: &#123;access_token&#125;&quot;) # ---------- 调用接口 ---------- nc_url = &quot;http://11.11.11.11:1111/nccloud/api/cmp/cmpapplyAdd/add&quot; request_body_str = json.dumps(payload, ensure_ascii=False, separators=(&#x27;,&#x27;, &#x27;:&#x27;)) self.log(f&quot;请求体: &#123;request_body_str&#125;&quot;) client_id = &quot;ldlldldldl&quot; biz_center = &quot;ncc22222&quot; repeat_check = &quot;Y&quot; pubKey = &quot;&quot; sign_str = client_id + request_body_str + pubKey signature = hashlib.sha256(sign_str.encode(&#x27;utf-8&#x27;)).hexdigest() self.log(f&quot;签名串: &#123;sign_str&#125;&quot;) self.log(f&quot;计算签名: &#123;signature&#125;&quot;) headers = &#123; &quot;Content-Type&quot;:&quot;application/json;charset=utf-8&quot;, &quot;access_token&quot;:access_token, &quot;client_id&quot;:client_id, &quot;biz_center&quot;:biz_center, &quot;repeat_check&quot;:repeat_check, &quot;signature&quot;:signature, &quot;groupcode&quot;:&quot;H&quot; &#125; self.log(f&quot;请求头:&#123;headers&#125;&quot;) response = requests.post(nc_url, json=payload, headers=headers, timeout=30) self.log(f&quot;NC接口响应状态码: &#123;response.status_code&#125;&quot;) self.log(f&quot;NC接口响应原始内容: &#123;response.text&#125;&quot;) self.log(f&quot;00请求URL:&#123;nc_url&#125;&quot;) self.log(f&quot;00请求体:&#123;json.dumps(payload, ensure_ascii=False)&#125;&quot;) self.log(f&quot;00请求头:&#123;headers&#125;&quot;) # 准备部门列表用于日志（每个部门一条记录） dept_list = [ &#123; &quot;dept_id&quot;:dept_id, &quot;dept_name&quot;:info[&quot;name&quot;], &quot;dept_number&quot;:info[&quot;number&quot;], &quot;amount&quot;:info[&quot;amount&quot;] &#125; for dept_id, info in dept_summary.items() ] if response.status_code == 200: try: result = response.json() self.log(f&quot;NC接口返回JSON: &#123;result&#125;&quot;) if result.get(&quot;success&quot;): vbillno = result.get(&quot;data&quot;, &#123;&#125;).get(&quot;vbillno&quot;) # 记录成功日志（每个部门一条，带相同的单据号） self._record_pre_accrual_data(month, dept_list, total_actual, True, vbillno) return &#123;&quot;result&quot;: &quot;success&quot;, &quot;vbillno&quot;: vbillno&#125; else: error_msg = result.get(&quot;message&quot;, &quot;未知错误&quot;) # 记录失败日志（每个部门一条，带错误信息） self._record_pre_accrual_data(month, dept_list, total_actual, False, error_message=error_msg) return &#123;&quot;error&quot;: error_msg&#125; except Exception as json_err: self.log(f&quot;JSON解析失败: &#123;str(json_err)&#125;&quot;) self._record_pre_accrual_data(month, dept_list, total_actual, False, error_message=f&quot;JSON解析失败: &#123;response.text&#125;&quot;) return &#123;&quot;error&quot;: f&quot;NC接口返回非JSON格式: &#123;response.text&#125;&quot;&#125; else: self.log(f&quot;NC接口返回非200状态码: &#123;response.status_code&#125;&quot;) self._record_pre_accrual_data(month, dept_list, total_actual, False, error_message=f&quot;HTTP &#123;response.status_code&#125;&quot;) return &#123;&quot;error&quot;: f&quot;NC接口返回错误状态码: &#123;response.status_code&#125;&quot;&#125; except Exception as e: error_msg = str(e) self.log(f&quot;工资推送异常: &#123;error_msg&#125;&quot;) # 记录异常日志 try: if &#x27;month&#x27; in locals(): self._record_pre_accrual_data(month, [], 0.0, False, error_message=error_msg) else: self._record_pre_accrual_data(&quot;&quot;, [], 0.0, False, error_message=error_msg) except Exception as log_err: self.log(f&quot;记录失败日志时发生错误: &#123;log_err&#125;&quot;) return &#123;&quot;error&quot;: error_msg&#125; def _record_pre_accrual_data(self, month, dept_list, total_actual, success, vbillno=None, error_message=None): &quot;&quot;&quot; 记录预提工资推送日志（每个部门一条记录） month: 推送月份 dept_list: 部门列表，包含 dept_id, dept_name, dept_